"""Select one value from a JSON value by path.

A path is a list of segments, read exactly like a step's output binding: a
string is an object key, and an integer is a list index, counting from the
end when negative. When nothing is at the path, the tool fails, unless the
step gives it a `default`, which is then the result. A `null` found at the
path is a value, so `default` never replaces it.
"""

import json
import sys

TOOL = "json_select"
INPUTS = ("value", "path", "default")
REQUIRED = ("value", "path")


def fail(status, message):
    sys.stderr.write(message)
    sys.exit(status)


def read_inputs():
    inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

    for name in inputs:
        if name not in INPUTS:
            fail(2, f"{TOOL} does not take the input {name!r}.")

    for name in REQUIRED:
        if name not in inputs:
            fail(2, f"{TOOL} needs the input {name!r}.")

    return inputs


def is_segment(segment):
    return isinstance(segment, str) or (isinstance(segment, int) and not isinstance(segment, bool))


def select(value, path):
    for segment in path:
        if isinstance(segment, str):
            if not isinstance(value, dict) or segment not in value:
                return False, f"missing object key {segment!r}"

            value = value[segment]
            continue

        if not isinstance(value, list):
            return False, f"expected a list for index {segment}"

        try:
            value = value[segment]
        except IndexError:
            return False, f"list index {segment} is out of range"

    return True, value


inputs = read_inputs()
path = inputs["path"]

if not isinstance(path, list) or not all(is_segment(segment) for segment in path):
    fail(2, f"{TOOL} needs 'path' to be a list of object keys and list indexes.")

found, result = select(inputs["value"], path)

if not found:
    if "default" not in inputs:
        shown = json.dumps(path, ensure_ascii=False)
        fail(1, f"{TOOL} found no value at path {shown}: {result}.")

    result = inputs["default"]

sys.stdout.buffer.write(json.dumps({"value": result}, ensure_ascii=False).encode("utf-8"))
